svg.addEventListener('pointerdown',e=>{if(e.button!==0)return;const p=point(e);if(!p)return;if(!p.inside&&!inBuffer(e)&&tool){setTool(null);return;}if(tool&&inBuffer(e)){try{commit(M.storeOnBuffer(project,[{...makeObject(tool,p),id:crypto.randomUUID()}]),'');}catch(error){status(error.message,true);}return;}if(tool){const o={...makeObject(tool,p),id:crypto.randomUUID()},error=M.candidate(project,o);if(error){status(error,true);return;}const next=M.clone(project);next.objects.push(o);if(commit(next,o.name+' posé. R pour tourner, F pour sélectionner.')){choose([o.id]);draft();render();}return;}
 const bufferTarget=e.target.closest('[data-buffer-id]');if(bufferTarget){const o=bufferLayout(project).objects.find(o=>o.id===bufferTarget.dataset.bufferId),before=[...selection];choose([]);beginHold([o],p,e,'buffer',before);e.preventDefault();return;}const target=e.target.closest('[data-object-id]'),before=[...selection];if(!target){drag={kind:'box',start:p,current:p,base:e.shiftKey?before:[],before,moved:false};if(!e.shiftKey)choose([]);svg.setPointerCapture(e.pointerId);}else{const id=target.getAttribute('data-object-id');if(e.shiftKey){const ids=new Set(selection);ids.has(id)?ids.delete(id):ids.add(id);choose([...ids]);}else if(!selection.has(id))choose([id]);if(!selection.has(id)){render();draft();return;}beginHold(project.objects.filter(o=>selection.has(o.id)),p,e,'board',before);}e.preventDefault();render();});
svg.addEventListener('pointermove',e=>{const p=point(e);if(!p)return;$('pointer').textContent='R : tourner · Échap : annuler · Pointillés : réseau logique non routé';if(drag){const dx=p.x-drag.start.x,dy=p.y-drag.start.y;drag.moved=dx!==0||dy!==0;if(drag.kind==='box'){drag.current=p;choose([...new Set([...drag.base,...M.boxSelection({...project,objects:project.objects.filter(shown)},drag.start,p,level)])]);draw();}else{drag.point=p;drag.mouse={clientX:e.clientX,clientY:e.clientY};drag.active=drag.moved||drag.turns!==0;updateHold();}}else if(tool){ghost=p.inside||inBuffer(e)?makeObject(tool,p):null;draw();}});
svg.addEventListener('pointerup',e=>{if(!drag)return;if(drag.kind==='box'){drag=null;draft();render();return;}const p=point(e);drag.point=p||drag.point;drag.mouse={clientX:e.clientX,clientY:e.clientY};const current=drag,held=heldObjects();drag=null;groupGhost=null;$('bufferArea').classList.remove('drop-target');$('dragBadge').hidden=true;if(!current.active){draft();render();return;}try{if(inBuffer(e)){if(commit(M.storeOnBuffer(project,held),held.length+' objet(s) mis de côté. Leurs liaisons ont été détachées.'))choose([]);}else if(!p?.inside){if(commit(M.removeSelection(project,current.ids),held.length+' objet(s) supprimé(s) hors du cadre.'))choose([]);}else{if(commit(M.placeHeld(project,held),held.length+' objet(s) posé(s).'))choose(current.ids);}draft();render();}catch(error){render();status(error.message+' · prise annulée, objets conservés.',true);}});
