function rotate(mode='auto'){if(drag?.kind==='move'){drag.turns=(drag.turns+1)%4;drag.active=true;updateHold();return;}if(tool&&mode!=='selected'){placementRotation=(placementRotation+90)%360;if(ghost)ghost.rotation=placementRotation;draw();status('Orientation de placement : '+placementRotation+'°.');return;}if(selection.size>1){const objects=project.objects.filter(o=>selection.has(o.id)),boxes=objects.map(M.bounds),anchor={x:(Math.min(...boxes.map(b=>b.minX))+Math.max(...boxes.map(b=>b.maxX)))/2,y:(Math.min(...boxes.map(b=>b.minY))+Math.max(...boxes.map(b=>b.maxY)))/2};try{commit(M.placeHeld(project,M.heldTransform(objects,anchor,anchor,1)),objects.length+' objets tournés.');}catch(error){status(error.message,true);}return;}const o=selectedObject();if(!o)return;const changed={...o,rotation:(o.rotation+90)%360},error=M.candidate(project,changed);if(error){status(error,true);return;}const next=M.clone(project);next.objects[next.objects.findIndex(b=>b.id===o.id)]=changed;commit(next,'Objet tourné de 90°.');}
