$('deleteSelection').addEventListener('click',remove);
$('properties').addEventListener('submit',e=>{e.preventDefault();const o=selectedObject();if(!o){if(selection.size>1)status('Sélectionnez un seul objet pour le tourner.');return;}const changed={...o,name:$('objectName').value.trim()};for(const k of ['x','y','w','d','rotation','z','h'])changed[k]=Number($(k).value);changed.recipe=$('recipe').value||null;changed.clock=Number($('clock').value)/100;if(!Number.isFinite(changed.clock)||changed.clock<=0||changed.clock>1){status('Cadence attendue entre 1 et 100 %. ',true);return;}if(changed.recipe&&plannerData.recipes[changed.recipe].type!==changed.type){status('Cette recette ne correspond pas à la machine.',true);return;}const error=M.candidate(project,changed);if(error){status(error,true);return;}const next=M.clone(project);next.objects[next.objects.findIndex(b=>b.id===o.id)]=changed;commit(next,'Propriétés appliquées.');});
$('projectName').addEventListener('input',()=>{const name=$('projectName').value.trim();if(name){project.name=name;dirty=true;draft();$('saveState').textContent='Nom modifié · Enregistrer pour conserver cette version.';}});
$('projectName').addEventListener('change',()=>{const name=$('projectName').value.trim();if(!name){$('projectName').value=project.name;status('Le projet doit avoir un nom.',true);return;}if(name===project.name)return;commit({...M.clone(project),name},'Nom du projet modifié.');});
$('rotate').addEventListener('click',()=>rotate('selected'));$('duplicate').addEventListener('click',duplicate);$('delete').addEventListener('click',remove);$('undo').addEventListener('click',()=>history('undo'));$('redo').addEventListener('click',()=>history('redo'));$('save').addEventListener('click',save);
async function discardAllowed(){return !dirty||!(project.objects.length+project.buffer.length)||await askConfirm('Le brouillon actuel contient des changements non enregistrés. Continuer et le remplacer ?');}
