document.addEventListener('keydown',e=>{if($('confirmDialog').open||$('previewDialog').open||editorView==='design')return;const field=e.target.closest('input,select,textarea');if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();$('projectName').blur();save();return;}if(field)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();history(e.shiftKey?'redo':'undo');}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();history('redo');}else if(e.key==='Escape'||(e.key.toLowerCase()==='f'&&!e.ctrlKey&&!e.metaKey&&!e.altKey)){e.preventDefault();if(drag?.kind==='move'){choose(drag.before);setTool(null);}else setTool(null);}else if(e.key.toLowerCase()==='r'&&!e.ctrlKey&&!e.metaKey&&!e.altKey){e.preventDefault();rotate();}else if(e.key.toLowerCase()==='d'&&!e.ctrlKey&&!e.metaKey){e.preventDefault();duplicate();}else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();remove();}});
