async function reflowDimensions(dimensions,storeys,result){
 const source=project,n=Number(storeys);if(!Number.isInteger(n)||n<1||n>32)throw new Error('Choisissez entre 1 et 32 étages.');
 if(!plannerData||!source.flows?.outputs?.length)throw new Error('Définissez les entrées et sorties dans Calculator avant de réorganiser.');
 const generation=D.generation({...source.generation,shape:'rectangle',sizing:'fixed',storeyMode:n===1?'single':'limited',maxStoreys:n}),height=Math.max(32,Math.ceil(n*16/8)*8),next=await planInBackground({id:source.id,source:M.clone(source),flows:source.flows,data:plannerData,generation,structure:source.structure,dimensions:{...dimensions,height}},result);
 if(project!==source)throw new Error('Le plan a changé pendant le calcul. Relancez la réorganisation.');
 if(next.size!==dimensions.size||M.depth(next)!==dimensions.depth)throw new Error('Ce style exige un autre terrain. Choisissez le kit M05 procédural pour conserver le format.');
 if((next.floors?.length||1)>n)throw new Error('Le nombre d’étages demandé ne suffit pas pour cette chaîne.');
 if(!commit(next,''))throw new Error('Cette implantation ne respecte pas les contraintes. Le plan initial est conservé.');choose([]);level=0;$('formatReflow').hidden=true;$('formatError').hidden=true;$('freeDimensions').open=false;render();
}
