$('flowSearch').onkeydown=e=>{const options=[...$('resourceOptions').querySelectorAll('button')];if(e.key==='Escape'){e.preventDefault();e.stopPropagation();closeResources();return;}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if($('resourceOptions').hidden)searchResources();const rows=[...$('resourceOptions').querySelectorAll('button')];if(!rows.length)return;resourceIndex=(resourceIndex+(e.key==='ArrowDown'?1:-1)+rows.length)%rows.length;rows.forEach((o,i)=>o.setAttribute('aria-selected',i===resourceIndex));$('flowSearch').setAttribute('aria-activedescendant',rows[resourceIndex].id);rows[resourceIndex].scrollIntoView({block:'nearest'});}else if(e.key==='Enter'&&!$('resourceOptions').hidden){e.preventDefault();(options[resourceIndex]||options[0])?.click();}};
