// Partition faces and line segments in world space so opaque floors and machines
// hide geometry behind them, including while the camera rotates.
function paintPreviewSolids(view,faces,lines){
 // Large source modules need a bounded software fallback when WebGL is absent.
 if(faces.length>6000){const depth=item=>item.coords.reduce((n,p)=>n+p.reduce((v,x,i)=>v+x*view.near[i],0),0)/item.coords.length;for(const item of [...faces,...lines].sort((a,b)=>depth(a)-depth(b))){const source=item.source.cloneNode(true);source.setAttribute('points',item.coords.map(view.project).map(q=>q.join(',')).join(' '));view.svg.append(source);}view.svg.dataset.renderer='svg-simplified';return;}
 const dot=(a,b)=>a.reduce((v,x,i)=>v+x*b[i],0),sub=(a,b)=>a.map((x,i)=>x-b[i]);
 const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]],epsilon=1e-6;
 const split=(item,plane)=>{
  const distances=item.coords.map(q=>dot(plane.normal,q)-plane.offset);
  if(distances.every(d=>Math.abs(d)<epsilon))return [null,null,item];
  if(distances.every(d=>d>=-epsilon))return [item,null,null];
  if(distances.every(d=>d<=epsilon))return [null,item,null];
  const front=[],back=[],count=item.coords.length;
  for(let i=0;i<count;i++){
   const a=item.coords[i],d=distances[i];
   if(d>=-epsilon)front.push(a);if(d<=epsilon)back.push(a);
   if(item.line&&i===count-1)break;
   const k=(i+1)%count,e=distances[k];
   if((d>epsilon&&e< -epsilon)||(d< -epsilon&&e>epsilon)){
    const t=d/(d-e),q=a.map((x,n)=>x+(item.coords[k][n]-x)*t);front.push(q);back.push(q);
   }
  }
  return [{...item,coords:front},{...item,coords:back},null];
 };
 const insert=(tree,item)=>{
  if(!tree){const normal=cross(sub(item.coords[1],item.coords[0]),sub(item.coords[2],item.coords[0]));const length=Math.hypot(...normal);normal.forEach((x,i)=>normal[i]=x/length);return {normal,offset:dot(normal,item.coords[0]),items:[item],front:null,back:null};}
  const [front,back,same]=split(item,tree);
  if(same)tree.items.push(same);if(front)tree.front=insert(tree.front,front);if(back)tree.back=insert(tree.back,back);return tree;
 };
 let root=null;for(const face of faces)root=insert(root,face);
 const draw=item=>{const n=item.source.cloneNode(true);n.setAttribute('points',item.coords.map(view.project).map(q=>q.join(',')).join(' '));view.svg.append(n);};
 // Keep empty-space segments in leaves as well, for the same traversal as faces.
 const attach=(tree,item)=>{
  if(!tree)return {normal:[0,0,0],offset:0,items:[item],front:null,back:null,leaf:true};
  if(tree.leaf){tree.items.push(item);return tree;}
  const [front,back,same]=split(item,tree);if(same)tree.items.push(same);if(front)tree.front=attach(tree.front,front);if(back)tree.back=attach(tree.back,back);return tree;
 };
 for(const line of lines)root=attach(root,line);
 const visit=tree=>{if(!tree)return;const near=dot(tree.normal,view.near)>=0;visit(near?tree.back:tree.front);for(const item of tree.items)draw(item);visit(near?tree.front:tree.back);};
 visit(root);
}
