function hideMachineTooltip(){if(tooltipFrame)cancelAnimationFrame(tooltipFrame);tooltipFrame=0;tooltipPointer=null;if(machineTooltip)machineTooltip.hidden=true;}
function showMachineTooltip(pointer){
 if(!pointer||previewDrag||!previewPickView||!previewPickFaces.length){hideMachineTooltip();return;}
 const svg=$('previewIso'),matrix=svg.getScreenCTM();if(!matrix){hideMachineTooltip();return;}
 const at=svg.createSVGPoint();at.x=pointer.clientX;at.y=pointer.clientY;const local=at.matrixTransform(matrix.inverse()),name=PreviewPicking.hit(previewPickFaces,previewPickView,[local.x,local.y],$('previewOpaque').checked);
 if(!name){hideMachineTooltip();return;}
 const parent=$('previewDialog').open?$('previewDialog'):document.body;
 if(!machineTooltip){machineTooltip=document.createElement('div');machineTooltip.id='machineTooltip';machineTooltip.className='machine-tooltip';machineTooltip.setAttribute('role','tooltip');}
 if(machineTooltip.parentElement!==parent)parent.append(machineTooltip);
 machineTooltip.textContent=name;machineTooltip.hidden=false;
 machineTooltip.style.left=Math.max(8,Math.min(pointer.clientX+14,innerWidth-machineTooltip.offsetWidth-12))+'px';machineTooltip.style.top=Math.max(8,Math.min(pointer.clientY+14,innerHeight-machineTooltip.offsetHeight-12))+'px';
}
function queueMachineTooltip(e){tooltipPointer={clientX:e.clientX,clientY:e.clientY};if(tooltipFrame)return;tooltipFrame=requestAnimationFrame(()=>{tooltipFrame=0;showMachineTooltip(tooltipPointer);});}
function openPreview(resetCamera=false){mountPreview('dialog');if(drag?.active)return;if(resetCamera===true){previewCamera.yaw=defaultPreviewYaw();previewCamera.pitch=Math.PI/6;previewCamera.zoom=1;}tool=null;ghost=null;drag=null;groupGhost=null;draw();$('calculatorMenu').open=false;if(!$('previewDialog').open)$('previewDialog').showModal();renderPreview();}
$('openPreview').onclick=()=>{$('previewTitle').textContent=nativePreviewProject===project?'Réseau natif prêt pour l’export':'Vue 3D du blueprint';openPreview();};
$('previewOpaque').onchange=()=>renderPreview();
function closePreview(){hideMachineTooltip();$('previewDialog').close();}
$('closePreview').onclick=closePreview;$('returnToWorkshop').onclick=closePreview;
for(const button of document.querySelectorAll('[data-preview-axis]'))button.onclick=()=>{$('previewAxis').value=button.dataset.previewAxis;for(const other of document.querySelectorAll('[data-preview-axis]'))other.setAttribute('aria-pressed',other===button);renderPreview();};
if(new URLSearchParams(location.search).has('calculator'))$('calculatorMenu').open=true;

function isCompactCase(flows){return flows.inputs.length===1&&['Desc_OreIron_C','Desc_IronIngot_C'].includes(flows.inputs[0].id)&&flows.outputs.length===1&&flows.outputs[0].id==='Desc_IronPlateReinforced_C'&&flows.outputs[0].rate>=.2&&flows.outputs[0].rate<=10&&Math.abs(flows.inputs[0].rate-12*flows.outputs[0].rate)<1e-6;}
function finishCalculator(){hideMachineTooltip();$('previewOpaque').checked=true;$('technicalCutaway').checked=false;$('livingCutaway').checked=false;choose([]);level=project.nativeProfile==='clean-manifold-v1'?5:0;tool=null;$('calculatorMenu').open=false;if($('previewDialog').open)$('previewDialog').close();previewCamera.yaw=defaultPreviewYaw();previewCamera.pitch=Math.PI/6;previewCamera.zoom=1;render();setEditorView('design');}
function calculatorFlows(){if(!calculatorDraft)calculatorDraft={flows:M.clone(project.flows)};return calculatorDraft.flows;}
$('prepareCompact').onclick=()=>{$('layoutStyle').value='compact';$('storeyMode').value='auto';$('calcFormat').value='auto';calculatorShape='rectangle';syncIntentChoices();$('generate').click();};

function drawInterfaces(){if(!project.nativeProfile||!visibleLayers.has('logistics'))return;for(const kind of ['input','output']){const info=project.layoutInfo?.[kind],o=project.objects.find(o=>o.id===info?.objectId);if(!o||!M.visible(project,o,level))continue;const point=info.port?A.physicalPath(project,{from:o.id,native:{snap:true,fromPort:info.port}})?.[0]:{x:o.x,y:o.y};if(!point)continue;const g=node('g',{'pointer-events':'none'},$('connections'));node('circle',{cx:point.x,cy:point.y,r:.4,fill:'var(--lime)'},g);node('text',{x:point.x,y:point.y-1.8,fill:'var(--lime)','font-size':.8,'text-anchor':'middle'},g,(kind==='input'?'→ ':'')+info.label+(kind==='output'?(o.type==='storage'?' → coffre':' → sortie'):''));}}

function setFlowSide(side){if($('flowSide').value!==side){$('flowItem').value='';$('flowSearch').value='';$('flowRate').value='';closeResources();}$('flowSide').value=side;for(const button of document.querySelectorAll('[data-flow-side]'))button.setAttribute('aria-pressed',button.dataset.flowSide===side);}
for(const button of document.querySelectorAll('[data-flow-side]'))button.onclick=()=>setFlowSide(button.dataset.flowSide);
function requestPreviewFrame(){if(previewFrame||(!$('previewDialog').open&&editorView!=='design'))return;previewFrame=requestAnimationFrame(()=>{previewFrame=0;if($('previewDialog').open||editorView==='design')renderPreview(true);});}
function orbitPreview(dx,dy){hideMachineTooltip();previewCamera.yaw=(previewCamera.yaw+dx*.008)%(Math.PI*2);previewCamera.pitch=Math.max(.12,Math.min(Math.PI/2-.06,previewCamera.pitch-dy*.006));requestPreviewFrame();}
function zoomPreview(delta){hideMachineTooltip();previewCamera.zoom=Math.max(.5,Math.min(6,previewCamera.zoom*Math.exp(-delta*.0015)));requestPreviewFrame();}
function stopPreviewDrag(){if(previewDrag&&$('previewIso').hasPointerCapture(previewDrag.id))$('previewIso').releasePointerCapture(previewDrag.id);previewDrag=null;$('previewIso').classList.remove('orbiting');}
$('previewIso').addEventListener('pointerdown',e=>{hideMachineTooltip();if(e.button!==0||previewDrag)return;e.preventDefault();$('previewIso').focus({preventScroll:true});previewDrag={id:e.pointerId,x:e.clientX,y:e.clientY};$('previewIso').setPointerCapture(e.pointerId);$('previewIso').classList.add('orbiting');});
$('previewIso').addEventListener('pointermove',e=>{if(!previewDrag||e.pointerId!==previewDrag.id)return;const dx=e.clientX-previewDrag.x,dy=e.clientY-previewDrag.y;previewDrag.x=e.clientX;previewDrag.y=e.clientY;orbitPreview(dx,dy);});
$('previewIso').addEventListener('pointermove',queueMachineTooltip);$('previewIso').addEventListener('pointerleave',()=>{tooltipPointer=null;if(tooltipFrame)cancelAnimationFrame(tooltipFrame);tooltipFrame=0;hideMachineTooltip();});
for(const event of ['pointerup','pointercancel','lostpointercapture'])$('previewIso').addEventListener(event,stopPreviewDrag);
$('previewIso').addEventListener('pointerup',queueMachineTooltip);
$('previewIso').addEventListener('wheel',e=>{e.preventDefault();zoomPreview(Math.max(-500,Math.min(500,e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?400:1))));},{passive:false});
$('previewIso').addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-','Home'].includes(e.key)){e.preventDefault();if(e.key==='Home')$('resetPreviewCamera').click();else if(['+','=','-'].includes(e.key))zoomPreview(e.key==='-'?100:-100);else orbitPreview(e.key==='ArrowLeft'?-15:e.key==='ArrowRight'?15:0,e.key==='ArrowUp'?-15:e.key==='ArrowDown'?15:0);}});
$('resetPreviewCamera').onclick=()=>{previewCamera.yaw=defaultPreviewYaw();previewCamera.pitch=Math.PI/6;previewCamera.zoom=1;requestPreviewFrame();};
$('previewDialog').addEventListener('close',()=>{if(editorView==='design'){mountPreview('design');renderPreview();}stopPreviewDrag();if(previewFrame)cancelAnimationFrame(previewFrame);previewFrame=0;});

