function renderArchitecturePresets(d){
 if(architectureShownFamily!==d.family){architectureChoice=D.PRESETS[d.family]&&!D.PRESETS[d.family].hidden&&d.family!=='m05'?d.family:null;architectureShownFamily=d.family;}
 $('unlockArchitecture').hidden=Object.keys(D.PRESETS).every(id=>D.presetAvailable(id,d.packs));
 const options=$('architectureDesignOptions');options.replaceChildren();const groups=new Map();
 for(const[id,style]of Object.entries(D.PRESETS)){if(id==='m05'||style.hidden)continue;const category=style.nativeStudy?D.CATALOG.studies[style.nativeStudy].category:'Procédural';if(!groups.has(category))groups.set(category,[]);groups.get(category).push([id,style]);}
 for(const[category,entries]of groups){const group=el('div',undefined,'architecture-picker-group'),heading=el('div',category,'architecture-picker-group-title');group.setAttribute('role','group');group.setAttribute('aria-label',category);heading.setAttribute('aria-hidden','true');group.append(heading);for(const[id,style]of entries){const option=el('button',undefined,'architecture-picker-option');option.type='button';option.setAttribute('role','option');option.tabIndex=-1;option.dataset.design=id;option.disabled=!style.nativeStudy&&!D.presetAvailable(id,d.packs);option.setAttribute('aria-selected',String(architectureChoice===id));option.append(el('span',style.name),el('span','✓','architecture-picker-check'));option.lastChild.setAttribute('aria-hidden','true');if(option.disabled)option.title='Activer les packs nécessaires dans Contenu débloqué';option.onclick=()=>{architectureChoice=id;closeArchitecturePicker(true);renderArchitectureChoice();};option.onkeydown=architectureOptionKey;group.append(option);}options.append(group);}
 renderArchitectureChoice(d.packs);
 const family=D.PRESETS[d.family],study=!!family?.nativeStudy;$('architectureVariant').textContent=d.enabled&&family?'Appliqué : '+family.name+(d.family==='signature'?' · '+['Horizon','Faille','Ossature'][(d.seed-1)%3]:''):'Aucun habillage appliqué';$('refreshArchitecture').disabled=!family||!!family.nativeStudy;
 $('architectureGrammar').textContent=family?({signature:'Volumes composés',flat:'Façades planes',warehouse:'Blocs et baies en retrait',gallery:'Galeries et travées saillantes',terraces:'Étages en gradins'}[d.facadeForm])+' · '+({grid:'Ossature tramée',columns:'Montants verticaux',none:'Façade sobre'}[d.structure])+' · '+({classic:'Fenêtres régulières',paired:'Baies groupées',ribbon:'Bandeaux vitrés',alternating:'Travées alternées',upper:'Éclairage haut',full:'Façades vitrées'}[d.pattern])+' · '+({frame:'Portail encadré',porch:'Entrée avec brise-soleil',double:'Portique en retrait'}[d.entryTreatment]):'Appliquez un style, puis explorez ses variantes. Les machines et leurs réseaux gardent leur place.';
 if(study)$('architectureGrammar').textContent='Composition conservée, agrandie par travées de 8 m. La production est déplacée en bloc si nécessaire ; machines, recettes et réseaux gardent leurs positions relatives. Les planchers suivent les zones compatibles avec les volumes. Appliquer à nouveau adapte la création au plan actuel.';
 if(study&&D.CATALOG.studies[family.nativeStudy]?.designFirst&&!D.CATALOG.studies[family.nativeStudy].workshopCompatible)$('architectureGrammar').textContent='Maquette autonome : architecture, salles et circulations réservées. Ouvrez Examiner la création pour inspecter les niveaux ; le routage de production n’est pas inclus.';
 if(d.family==='compact')$('architectureGrammar').textContent='Carré de 48 à 96 m choisi selon la production. Machines et réseaux déplacés ensemble ; sol, inspection, éclairage mural et LED intégrés à la création. Hauteur utile : 16 m.';
 if(d.family==='atlas'&&!d.studyFitted)$('architectureGrammar').textContent='Étude composée à la main · 64 × 48 m · halle, atrium, galerie et tour technique · une composition fixe, sans variation aléatoire. Importez la maquette pour l’examiner.';
 if(d.family==='signature')$('architectureGrammar').textContent='Trois compositions maîtrisées · retraits selon la place disponible · vitrages encadrés en profondeur · rives et lames localisées. Éclairage émissif et passerelles fonctionnelles : prochaine étape. Les machines restent en place.';
 if(d.family==='classics'||family?.hidden)$('architectureGrammar').textContent='Anciennes familles réunies · Varier explore les matériaux, les ouvertures et les volumes. Vos projets existants conservent leur composition.';
 if(d.family==='m05-kit')$('architectureGrammar').textContent='Façades adaptées à la hauteur des murs · travées basses pour les petits plans · lanterneaux, pentes et sheds avec appuis. ↻ Murs varie les façades ; ↻ Toit change la composition et son orientation. Aucune marge décorative imposée en compact.';
 if(d.family==='m05')$('architectureGrammar').textContent='JazzFrank · modules natifs de 40 × 40 × 40 m. Angles C1/C2, façades M1–M6, toiture intérieure IN1. Varier change les modules en symétrie, sans étirer leurs pièces. IC1/IC2 et IN2 sont étudiés mais ne sont pas encore assemblés automatiquement.';
}
function renderArchitectureChoice(packs=packsFromForm()){const style=D.PRESETS[architectureChoice],study=style?.nativeStudy?D.CATALOG.studies[style.nativeStudy]:null;$('architectureDesignValue').textContent=style?.name||'Choisir un design';$('architectureChoiceDescription').textContent=(study?.summary||style?.description||'Sélectionnez un design dans la liste.')+(architectureChoice==='compact'?' 1 niveau de production · 16 m utiles. Extension verticale non prise en charge.':'');const action=$('architectureChoiceAction');action.hidden=!style;action.textContent=study?.designFirst&&!study.workshopCompatible?'Ouvrir la maquette':study?'Appliquer la création':'Appliquer ce design';action.disabled=!!style&&!D.presetAvailable(architectureChoice,packs);$('architectureStudyLink').hidden=!study;$('creationFitHint').hidden=!study||!!study.designFirst;$('creationStoreyChoices').hidden=!study||!!study.designFirst;const adapt=$('architectureFitCreation');adapt.hidden=!study||!!study.designFirst;adapt.disabled=!!study&&(!plannerData||!D.presetAvailable(architectureChoice,packs));if(study)$('architectureStudyLink').href='/creation?study='+style.nativeStudy;for(const option of $('architectureDesignOptions').querySelectorAll('[role=option]'))option.setAttribute('aria-selected',String(option.dataset.design===architectureChoice));}
function closeArchitecturePicker(focus=false){$('architectureDesignOptions').hidden=true;$('architectureDesign').setAttribute('aria-expanded','false');if(focus)$('architectureDesign').focus();}
function openArchitecturePicker(){const list=$('architectureDesignOptions');list.hidden=false;$('architectureDesign').setAttribute('aria-expanded','true');const option=list.querySelector('[aria-selected=true]:not(:disabled)')||list.querySelector('[role=option]:not(:disabled)');option?.focus();}
function architectureOptionKey(e){const options=[...$('architectureDesignOptions').querySelectorAll('[role=option]:not(:disabled)')],i=options.indexOf(e.currentTarget);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();options[e.key==='Home'?0:e.key==='End'?options.length-1:(i+(e.key==='ArrowDown'?1:-1)+options.length)%options.length]?.focus();}else if(e.key==='Escape'){e.preventDefault();closeArchitecturePicker(true);}else if(e.key==='Tab')closeArchitecturePicker();}
$('architectureDesign').onclick=()=>{$('architectureDesignOptions').hidden?openArchitecturePicker():closeArchitecturePicker();};
$('architectureDesign').onkeydown=e=>{if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();openArchitecturePicker();}else if(e.key==='Escape')closeArchitecturePicker();};
