$('architectureChoiceAction').onclick=async()=>{const id=architectureChoice,style=D.PRESETS[id],source=project;if(!style)return;if(style.nativeStudy&&D.CATALOG.studies[style.nativeStudy]?.designFirst&&!D.CATALOG.studies[style.nativeStudy].workshopCompatible){window.open('/creation?study='+style.nativeStudy,'_blank','noopener');return;}if(style.nativeStudy){try{let next;try{next=CreationFitting.apply(source,id,packsFromForm());}catch(error){if(id!=='compact'||!plannerData||!project.flows?.outputs?.length)throw error;next=await CreationFitting.reflow(source,id,packsFromForm(),plannerData,'single');}if(project!==source)throw new Error('Le plan a changé pendant la préparation. Relancez l’application de la création.');$('previewOpaque').checked=true;if(commit(next,style.name+' · création appliquée au blueprint · '+next.size+' × '+M.depth(next)+' m')){previewCamera.yaw=3.8;previewCamera.pitch=.43;previewCamera.zoom=1;renderPreview();}}catch(e){status(e.message,true);}return;}try{let next=M.clone(project);CreationLiving.restorePower(next);delete next.design.living;delete next.design.studyFitted;delete next.design.studyFloors;next.design=D.preset(id,{...D.settings(next.design),packs:packsFromForm()});D.envelope(next);commit(next,'');}catch(e){status(e.message,true);}};

