function flowReport(){if(!plannerData)return null;if(!flowCache.has(project))flowCache.set(project,FactoryFlowCore.analyze(project,plannerData,{linkAvailable:l=>{if(l.kind!=='belt')return true;if(!l.native)return !!beltRoute(project,l.from,l.to);const points=A.physicalPath(project,l),end=A.physicalPath(project,{from:l.to,native:{snap:true,fromPort:l.native.toPort}})?.[0],last=points?.[points.length-1];return !!last&&!!end&&Math.hypot(last.x-end.x,last.y-end.y,last.z-end.z)<.001;}}));return flowCache.get(project);}
function networkDiagnostic(p,link,data){
 const base=A.beltDiagnostic(p,link,data),report=p===project?flowReport():null,f=report?.links.get(link);if(report&&!report.converged)return {...base,state:'unknown',color:'#99a5af',label:'Estimation partielle : calcul interrompu.'};if(!f||link.kind==='power')return base;
 const color={blocked:'#ef786c',busy:'#e8b85c',ok:'#7fd5a0'}[f.state];return {...base,...f,color,rate:f.demand??f.actual,served:f.actual,label:(plannerData?.names[f.item]||f.item)+' · '+formatRate(f.actual)+' / '+f.capacity+'/min · charge '+formatRate(f.load)+' %'+(f.efficiency===null?'':' · objectif servi '+formatRate(f.efficiency)+' %')+' · estimation théorique'};
}
function renderInspector(){
 const selectionKey=[...selection].sort().join(',');if(selectionKey!==inspectorSelectionKey){inspectorSelectionKey=selectionKey;if(editorView==='construction')animatePanel($('selectionCard'));}
 const panel=$('selectionCard');panel.hidden=editorView!=='construction';$('properties').hidden=true;$('multiSelection').hidden=true;
 const chosen=project.objects.filter(o=>selection.has(o.id)),machines=chosen.filter(o=>['smelter','constructor','assembler'].includes(o.type)),io=chosen.length===1&&chosen[0].type==='port'?chosen[0]:null;
 $('noSelection').hidden=!!machines.length||!!io;$('noSelection').textContent='Cliquez sur une machine pour choisir sa recette, ou sur une entrée / sortie pour définir son flux. Les autres éléments logistiques se déplacent directement sur le plan.';
 $('inspectorTitle').textContent=io?(io.io?.side==='output'?'Sortie':'Entrée'):machines.length===1?M.TYPES[machines[0].type].name:machines.length?machines.length+' machines':'Sélection';
 $('interfacePanel').hidden=!io;const rows=$('recipeSelection');rows.replaceChildren();
 for(const type of ['smelter','constructor','assembler']){const list=machines.filter(o=>o.type===type);if(!list.length)continue;const label=el('label',M.TYPES[type].name+(list.length>1?' × '+list.length:''),'recipe-row'),select=el('select');select.dataset.recipeType=type;select.setAttribute('aria-label','Recette '+M.TYPES[type].name);const mixed=new Set(list.map(o=>o.recipe||''));const empty=el('option',mixed.size>1?'Recettes différentes…':'Aucune recette');empty.value='';select.append(empty);for(const [id,r]of Object.entries(plannerData?.recipes||{}).filter(([,r])=>r.type===type)){const option=el('option',r.name);option.value=id;select.append(option);}select.value=mixed.size===1?[...mixed][0]:'';select.onchange=()=>{try{commit(FactoryFlowCore.assignRecipe(project,list.map(o=>o.id),select.value,plannerData),'');}catch(e){status(e.message,true);}};label.append(select);rows.append(label);}
 if(io){const spec=io.io||{side:/sortie/i.test(io.name)?'output':'input',item:null,rate:null};$('inspectorTitle').textContent=spec.side==='input'?'Entrée':'Sortie';$('ioItem').value=spec.item||'';$('ioSearch').value=plannerData?.names[spec.item]||'';$('ioRate').value=spec.rate??'';$('interfaceHelp').textContent=spec.side==='input'?'Ce qui arrive dans cette usine. Chaque entrée possède son propre débit.':'Ce qui doit sortir de cette usine. Débit vide : estimer le maximum disponible.';$('ioRate').placeholder=spec.side==='input'?'Débit disponible requis':'Auto · maximum disponible';$('routeFromInterface').hidden=false;const estimate=flowReport()?.endpoints.get(io.id);$('interfaceEstimate').textContent=estimate?formatRate(estimate.actual)+'/min '+(spec.side==='input'?'distribué(s)':'atteignable(s)')+(estimate.efficiency===null?'':' · '+formatRate(estimate.efficiency)+' % de l’objectif')+(spec.side==='input'&&spec.rate?' · '+formatRate(100*estimate.actual/spec.rate)+' % de l’entrée utilisés':'')+' · théorique'+(!flowReport()?.converged?' · analyse partielle':'')+(flowReport()?.issues.length?' · '+flowReport().issues[0]:''):spec.item?'Reliez ce repère au réseau pour estimer son débit.':'Choisissez une ressource puis appliquez.';}
 $('ioOptions').hidden=true;$('ioSearch').setAttribute('aria-expanded','false');
}
function interfaceCandidates(){const query=$('ioSearch').value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),list=$('ioOptions');list.replaceChildren();for(const [id,name]of Object.entries(plannerData?.names||{}).filter(([,name])=>name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(query))){const button=el('button',name);button.type='button';button.setAttribute('role','option');button.onclick=()=>{$('ioItem').value=id;$('ioSearch').value=name;list.hidden=true;$('ioSearch').setAttribute('aria-expanded','false');$('ioRate').focus();};list.append(button);}list.hidden=false;$('ioSearch').setAttribute('aria-expanded','true');}
