$('ioSearch').onkeydown=e=>{if(e.key==='Escape'){$('ioOptions').hidden=true;e.stopPropagation();}if(e.key==='Enter'){e.preventDefault();$('ioOptions').querySelector('button')?.click();}};
$('saveInterface').onclick=()=>{const current=selectedObject();if(!current||current.type!=='port')return;const side=current.io?.side||(/sortie/i.test(current.name)?'output':'input'),item=$('ioItem').value,raw=$('ioRate').value.trim(),rate=raw?Number(raw):null;if(!plannerData?.names[item]){status('Choisissez une ressource dans la liste.',true);return;}if(side==='input'&&rate===null||rate!==null&&(!Number.isFinite(rate)||rate<=0||rate>100000)){status('Indiquez un débit positif pour cette entrée (maximum 100 000/min).',true);return;}const next=M.clone(project),o=next.objects.find(o=>o.id===current.id);o.io={side,item,rate};o.name=(side==='input'?'Entrée · ':'Sortie · ')+plannerData.names[item];commit(next,'');};
function buildNetwork(){try{
 const mode=$('routeCapacity').value,result=WorkshopNetwork.build(project,plannerData,{capacity:mode==='auto'?null:Number(mode)});
 if(commit(result.project,'')){networkSummaryProject=project;const endpoints=[...result.report.endpoints.values()].filter(e=>e.side==='output');$('networkResult').textContent=result.machines+' machine(s) reliée(s)'+(result.junctions?' · '+result.junctions+' répartiteur(s) / fusion(s)':'')+' · '+endpoints.map(e=>(plannerData.names[e.item]||e.item)+' '+formatRate(e.actual)+'/min'+(e.efficiency===null?'':' · '+formatRate(e.efficiency)+' %')).join(' · ')+(result.unused?' · '+result.unused+' machine(s) hors chaîne':'');}
 }catch(error){$('networkResult').textContent=error.message;status(error.message,true);}}
