function projectFlowText(p){
 const describe=side=>((p.flows?.[side]?.length?p.flows[side]:p.objects.filter(o=>o.io?.side===(side==='inputs'?'input':'output')&&o.io.item).map(o=>({id:o.io.item,rate:o.io.rate})))||[]).map(r=>(plannerData?.names[r.id]||r.id.replace(/^Desc_|_C$/g,''))+' '+(r.rate==null?'auto':formatRate(r.rate)+'/min')).join(' + ')||'à définir';
 return 'Input : '+describe('inputs')+' → Output : '+describe('outputs');
}
const PROJECT_TRASH=LIBRARY+'.trash';
function deleteProject(id){
 const p=library.find(p=>p.id===id);if(!p)return;
 try{const trash=JSON.parse(localStorage.getItem(PROJECT_TRASH)||'[]');trash.push(M.clone(p));localStorage.setItem(PROJECT_TRASH,JSON.stringify(trash));const next=library.filter(p=>p.id!==id);localStorage.setItem(LIBRARY,JSON.stringify(next));library=next;refreshLibrary();if(project.id===id){dirty=true;draft();}refreshProjectTrash();render();}
 catch{status('Suppression impossible : le stockage du navigateur est indisponible.',true);}
}
function refreshProjectTrash(){
 const host=$('projectCards').parentElement;let button=$('restoreDeletedProject');if(!button){button=el('button','↶ Restaurer le dernier projet supprimé');button.id='restoreDeletedProject';host.append(button);button.onclick=()=>{try{const trash=JSON.parse(localStorage.getItem(PROJECT_TRASH)||'[]'),p=trash.pop();if(!p)return;const next=library.filter(row=>row.id!==p.id);next.push(M.read(p));localStorage.setItem(LIBRARY,JSON.stringify(next));library=next;localStorage.setItem(PROJECT_TRASH,JSON.stringify(trash));refreshLibrary();refreshProjectTrash();}catch{status('Restauration impossible.',true);}};}
 try{button.hidden=!JSON.parse(localStorage.getItem(PROJECT_TRASH)||'[]').length;}catch{button.hidden=true;}
}
refreshProjectTrash();
