const advanceSeed=n=>n%999+1;
function refreshArchitecture(which){
 try{const next=M.clone(project),d=D.settings(next.design);if(which==='roof'){d.roof=true;d.roofSeed=advanceSeed(d.roofSeed);if(D.PRESETS[d.family]){const layouts=D.PRESETS[d.family].layouts;d.roofLayout=layouts[(d.roofSeed-1)%layouts.length];}}else{d.seed=advanceSeed(d.seed);if(D.PRESETS[d.family]){const patterns=D.PRESETS[d.family].patterns;d.pattern=patterns[(d.seed-1)%patterns.length];}}d.enabled=true;next.design=d;D.envelope(next);commit(next,'');}
 catch(error){status(error.message+' Le projet est conservé.',true);}
}
$('refreshWalls').onclick=()=>refreshArchitecture('walls');$('refreshRoof').onclick=()=>refreshArchitecture('roof');
$('varyLayout').onclick=async()=>{
 const source=project,button=$('varyLayout'),result=$('variationResult');button.disabled=true;result.classList.remove('error');
 try{if(!plannerData)throw new Error('Catalogue en cours de chargement.');if(!source.flows?.outputs?.length)throw new Error('Ajoutez les entrées/sorties dans Calculator pour réorganiser cette usine.');const generation=D.generation({...source.generation,shape:designShape,sizing:$('format').value==='auto'?'auto':'fixed',plot:designTerrain(),reserveCladding:$('reserveCladding').checked,layoutStyle:$('variationLayout').value,pitch:$('variationPitch').value==='minimum'?'minimum':Number($('variationPitch').value),storeyMode:$('variationStoreys').value,maxStoreys:Number($('variationMax').value)}),next=await planInBackground({id:source.id,source:M.clone(source),flows:source.flows,data:plannerData,generation,dimensions:designTerrain(),structure:source.structure},result);if(project!==source)throw new Error('Le projet a changé pendant le calcul. Relancez la réorganisation.');if(!commit(next,''))throw new Error('Cette implantation a été refusée. Le plan précédent est conservé.');finishCalculator();result.textContent='✓ '+WorkshopPlanning.describe(next);}
 catch(error){result.textContent=error.message;result.classList.add('error');}finally{button.disabled=false;}
};

$('nativePreview').onclick=async()=>{
 const button=$('nativePreview'),result=$('nativeProjectResult'),source=project;button.disabled=true;result.classList.remove('error');result.textContent='Calcul des convoyeurs et élévateurs natifs…';
 try{if(drag?.active)throw new Error('Terminez le déplacement avant de vérifier.');const response=await fetch('/api/blueprints/preview',{method:'POST',headers:{'Content-Type':'application/json','X-Factory-Tools':'local-viewer'},body:JSON.stringify({project:M.read(M.clone(source))})}),data=await response.json();showNativeIssues(data.issues||[]);$('nativeRepairBox').hidden=!data.repairAvailable;if(!response.ok)throw new Error(data.issues?.length?'Raccordements à corriger :\n• '+data.issues.slice(0,4).join('\n• ')+(data.issues.length>4?'\n… '+(data.issues.length-4)+' autres trajets. Consultez le détail ci-dessous.':''):data.error||'Vérification impossible.');if(project!==source)throw new Error('Le projet a changé pendant le calcul. Relancez la vérification.');nativePreviewProject=source;nativePreviewScene=data.verified.transportPreview||source;result.textContent=data.verified.belts+' convoyeurs · '+(data.verified.lifts||0)+' élévateurs natifs · '+(data.verified.foundations||0)+' fondations. Aperçu des trajets exportés, sans écriture dans le jeu. Toute modification du plan revient à l’aperçu de travail.';$('ioMenu').open=false;$('previewTitle').textContent='Réseau natif prêt pour l’export';openPreview(true);}catch(error){result.textContent=error.message;result.classList.add('error');}finally{button.disabled=false;}
};

function showNativeIssues(issues){const host=$('nativeIssueList');host.replaceChildren();for(const issue of issues)host.append(el('li',issue));$('nativeIssues').hidden=!issues.length;}

$('nativeRepair').onclick=async()=>{
 const source=project,button=$('nativeRepair'),result=$('nativeProjectResult');button.disabled=true;result.classList.remove('error');result.textContent='Conversion en réseau natif…';
 try{const response=await fetch('/api/workshop/repair',{method:'POST',headers:{'Content-Type':'application/json','X-Factory-Tools':'local-viewer'},body:JSON.stringify({project:M.read(M.clone(source))})}),data=await response.json();if(!response.ok)throw new Error(data.error||'Conversion impossible.');if(project!==source)throw new Error('Le plan a changé pendant la conversion. Relancez-la.');const next=M.read(data.project);if(!commit(next,''))throw new Error('La validation du plan a refusé la conversion.');choose([]);level=0;nativePreviewProject=null;nativePreviewScene=null;calculatorDraft=null;showNativeIssues([]);$('nativeRepairBox').hidden=true;$('ioMenu').open=false;setEditorView('design');result.textContent='Plan converti : '+data.verified.belts+' convoyeurs et '+data.verified.lifts+' élévateurs natifs. Débits conservés. Enregistrez ou exportez ; Annuler restaure l’ancien plan.';render();}catch(error){result.textContent=error.message;result.classList.add('error');}finally{button.disabled=false;}
};

$('centerArchitecture').onclick=()=>{try{commit(M.centerPlan(project),'');}catch(error){status(error.message,true);}};





$('reserveArchitecture').onclick=()=>{try{const next=D.reserveArchitecture(project);commit(next,'');}catch(error){status(error.message,true);}};
$('unlockArchitecture').onclick=()=>{const next=M.clone(project);next.design={...D.settings(next.design),packs:['concrete','metal','glass']};commit(next,'');};

